<div class="card form-card"><form method="post" action="<?= $link($entry?'/passwords/'.$entry['id'].'/save':'/organizations/'.$organization['id'].'/passwords/save') ?>" autocomplete="off"><?= $csrf ?><input type="hidden" name="revision" value="<?= $e($entry['revision']??0) ?>"><label>Name<input name="title" maxlength="190" required value="<?= $e($entry['title']??'') ?>"></label><label>Username<input name="username" maxlength="190" value="<?= $e($entry['username']??'') ?>"></label><label><?= $entry?'Replace password':'Password' ?><input name="secret" type="password" maxlength="10000" autocomplete="new-password" <?= $entry?'':'required' ?>></label><?php if($entry): ?><p class="help">Leave blank to keep the existing password.</p><?php endif; ?><label>URL<input name="url" type="url" maxlength="2048" value="<?= $e($entry['url']??'') ?>"></label><label>Configuration<select name="configuration_id"><option value="">Standalone password</option><?php foreach($configurations as $c): ?><option value="<?= $e($c['id']) ?>" <?= $selectedConfiguration===(int)$c['id']?'selected':'' ?>><?= $e($c['title']) ?><?= $c['visibility']==='internal'?' (internal)':'' ?></option><?php endforeach; ?></select></label><label>Visibility<select name="visibility"><option value="internal" <?= ($entry['visibility']??'internal')==='internal'?'selected':'' ?>>Internal only</option><option value="client" <?= ($entry['visibility']??'')==='client'?'selected':'' ?>>Client visible</option></select></label><p class="help">Client-visible passwords are available to assigned client users. A linked configuration must also be client visible.</p><label>Notes<textarea name="notes" maxlength="10000"><?= $e($entry['notes']??'') ?></textarea></label><div class="form-actions"><button class="button">Save password</button><a class="button secondary" href="<?= $link('/organizations/'.$organization['id'].'/passwords') ?>">Cancel</a></div></form></div>
